package com.ellenco.platform.domain;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;
@Entity @Table(name="ferramentas")public class ToolAsset{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,unique=true)private String patrimonio;@Column(nullable=false)private String nome;private String categoria;private String marca;private String modelo;private String numeroSerie;private String estadoConservacao="BOM";private String status="DISPONIVEL";private String localizacao;@ManyToOne@JoinColumn(name="galpao_id")private Warehouse galpao;@Column(precision=19,scale=2)private BigDecimal valor;private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public String getPatrimonio(){return patrimonio;}public void setPatrimonio(String v){patrimonio=v;}public String getNome(){return nome;}public void setNome(String v){nome=v;}public String getCategoria(){return categoria;}public void setCategoria(String v){categoria=v;}public String getMarca(){return marca;}public void setMarca(String v){marca=v;}public String getModelo(){return modelo;}public void setModelo(String v){modelo=v;}public String getNumeroSerie(){return numeroSerie;}public void setNumeroSerie(String v){numeroSerie=v;}public String getEstadoConservacao(){return estadoConservacao;}public void setEstadoConservacao(String v){estadoConservacao=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getLocalizacao(){return localizacao;}public void setLocalizacao(String v){localizacao=v;}public Warehouse getGalpao(){return galpao;}public void setGalpao(Warehouse v){galpao=v;}public BigDecimal getValor(){return valor;}public void setValor(BigDecimal v){valor=v;}public LocalDateTime getCreatedAt(){return createdAt;}}
